import{_ as a,a0 as i,w as m,s as d,ao as l,I as t,a1 as n,A as p,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Web 瀏覽器中啓用深色模式 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Web 瀏覽器中啓用深色模式 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Web 瀏覽器中啓用深色模式 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Web 瀏覽器中啓用深色模式 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser","title":"如何在 Web 瀏覽器中啓用深色模式","tag":"202211","desc":""},"relativePath":"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser.md","filePath":"[post].md"}'),s={name:"202211/20221030.0 ⭐️ How to Enable Dark Mode in Web Browser.md"};function u(b,e,f,h,g,w){const o=i("Link");return m(),d("div",null,[e[22]||(e[22]=l('<h1 id="如何在-web-瀏覽器中啓用深色模式" tabindex="-1">如何在 Web 瀏覽器中啓用深色模式 <a class="header-anchor" href="#如何在-web-瀏覽器中啓用深色模式" aria-label="Permalink to “如何在 Web 瀏覽器中啓用深色模式”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/08/110615dax28a8fhx13hxhi.jpg" alt=""></p><blockquote><p>本指南旨在幫助你在 Firefox、Chrome、Chromium 和 Edge 等流行的網頁瀏覽器中啓用深色模式。</p></blockquote><p>我們都喜歡深色模式。與標準淺色模式相比，許多人更喜歡它。許多桌面應用原生提供深色模式，而一些應用則是通過桌面環境的底層模式適應深色模式。</p><p>不可否認，我們都在網頁瀏覽器上花費了很多時間。我們很少使用桌面應用（除非你從事專門的工作，例如視頻編輯等）。因此，當你花費大量時間在瀏覽器中閲讀和學習時，你始終可以選擇深色模式。不過，對於網頁瀏覽器，啓用深色模式的方法略有不同。</p><p>本指南為你提供了在 Firefox、Chromium、Chrome 和 Edge 瀏覽器中啓用深色模式的簡單步驟。</p><h3 id="在網頁瀏覽器中啓用深色模式" tabindex="-1">在網頁瀏覽器中啓用深色模式 <a class="header-anchor" href="#在網頁瀏覽器中啓用深色模式" aria-label="Permalink to “在網頁瀏覽器中啓用深色模式”">​</a></h3><h4 id="在-firefox-中啓用深色模式" tabindex="-1">在 Firefox 中啓用深色模式 <a class="header-anchor" href="#在-firefox-中啓用深色模式" aria-label="Permalink to “在 Firefox 中啓用深色模式”">​</a></h4><p>打開 Firefox 並點擊右上角的菜單。</p><p>單擊 “<ruby>設置<rt>Settings</rt></ruby> &gt; <ruby>擴展和主題<rt>Extension and Themes</rt></ruby>”。</p><p>選擇 “<ruby>深色主題<rt>Dark Theme</rt></ruby>” 並點擊 “<ruby>啓用<rt>enable</rt></ruby>”。你應該會看到深色模式已應用於 Firefox。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Enable-dark-mode-in-Firefox.jpg" alt="Enable dark mode in Firefox"></p><p><em>在 Firefox 瀏覽器中啓用深色模式</em></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Firefox-in-Dark-Mode-1024x423.jpg" alt="Firefox in Dark Mode"></p><p><em>深色模式下的 Firefox</em></p><p>要將其還原，請按照相同的步驟並選擇淺色主題。</p><h4 id="chromium-和-chrome-中的深色模式" tabindex="-1">Chromium 和 Chrome 中的深色模式 <a class="header-anchor" href="#chromium-和-chrome-中的深色模式" aria-label="Permalink to “Chromium 和 Chrome 中的深色模式”">​</a></h4><p>默認情況下，Chromium 或 Chrome 不會預安裝任何深色主題。因此，你需要前往 Chrome 應用商店並下載你想要的深色主題。對於本指南，我會推薦超過一百萬用户使用的 “Morpheon Dark” 主題。</p><p>從 Chromium 瀏覽器打開 Morpheon Dark 主題頁面（以下鏈接）。</p>',19)),t("blockquote",null,[t("p",null,[t("strong",null,[n(o,{href:"https://chrome.google.com/webstore/detail/morpheon-dark/mafbdhjdkjnoafhfelkjpchpaepjknad?hl=en-GB"},{default:p(()=>[...e[0]||(e[0]=[r("Chrome 應用商店中的 Morpheon Dark 主題",-1)])]),_:1})])])]),e[23]||(e[23]=t("p",null,[r("點擊 “"),t("ruby",null,[r("添加到 Chrome"),t("rt",null,"Add To Chrome")]),r("” 按鈕。它應該會在 Chrome 中啓用。")],-1)),t("p",null,[e[2]||(e[2]=r("你可能想探索 Chrome 應用店中提供的其他深色或淺色主題。 ",-1)),n(o,{href:"https://chrome.google.com/webstore/category/collection/dark_themes"},{default:p(()=>[...e[1]||(e[1]=[r("訪問此頁面獲取所有深色主題的集合",-1)])]),_:1}),e[3]||(e[3]=r("。",-1))]),e[24]||(e[24]=t("p",null,"但是，你應該要記住的一件事是：此主題不會更改設置或上下文菜單，這是顯而易見的。因為它只是改變了瀏覽器窗口，而這些菜單（有時）是操作系統本身的一部分。",-1)),e[25]||(e[25]=t("p",null,[t("img",{src:"https://www.debugpoint.com/wp-content/uploads/2021/10/Chromium-Dark-Theme-1024x463.jpg",alt:"Chromium Dark Theme"})],-1)),e[26]||(e[26]=t("p",null,[t("em",null,"Chromium 深色主題")],-1)),e[27]||(e[27]=t("p",null,"對 Chrome 瀏覽器也遵循相同的步驟。",-1)),e[28]||(e[28]=t("h4",{id:"edge-瀏覽器-–-深色模式",tabindex:"-1"},[r("Edge 瀏覽器 – 深色模式 "),t("a",{class:"header-anchor",href:"#edge-瀏覽器-–-深色模式","aria-label":"Permalink to “Edge 瀏覽器 – 深色模式”"},"​")],-1)),t("p",null,[e[5]||(e[5]=r("但是，",-1)),n(o,{href:"https://www.debugpoint.com/2020/10/how-to-install-edge-ubuntu-linux/"},{default:p(()=>[...e[4]||(e[4]=[r("Edge 瀏覽器",-1)])]),_:1}),e[6]||(e[6]=r(" 默認帶有更好的深色主題。它允許你從設置中使用 GTK+、淺色和深色模式。",-1))]),e[29]||(e[29]=l('<p>打開 Edge 瀏覽器，點擊右上角的三個小點。</p><p>轉到 “<ruby>外觀<rt>Appearance</rt></ruby>” 並選擇 “<ruby>深色<rt>Dark</rt></ruby>”。這樣應該就好了。</p><p>Edge 的這種深色主題實現更好，因為它改變了上下文菜單和地址欄。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/10/Edge-in-Dark-Theme-1024x541.jpg" alt="Edge in Dark Theme"></p><p><em>深色主題的 Edge</em></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>如果你是高級用户，你可能不需要本指南。你可以自己弄清楚。</p><p>但我們為所有讀者涵蓋了所有基礎到高級教程。許多新的 Linux 用户可能不知道如何在瀏覽器中啓用深色模式。</p><p>所以，就是説，我希望這對你和其他人有幫助。如果你遇到任何問題，請在下面的評論框中告訴我。</p><hr>',10)),t("p",null,[e[8]||(e[8]=r("via: ",-1)),n(o,{href:"https://www.debugpoint.com/dark-mode-browser/"},{default:p(()=>[...e[7]||(e[7]=[r("https://www.debugpoint.com/dark-mode-browser/",-1)])]),_:1})]),t("p",null,[e[13]||(e[13]=r("作者：",-1)),n(o,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...e[9]||(e[9]=[r("Arindam",-1)])]),_:1}),e[14]||(e[14]=r(" 選題：",-1)),n(o,{href:"https://github.com/lkxed"},{default:p(()=>[...e[10]||(e[10]=[r("lkxed",-1)])]),_:1}),e[15]||(e[15]=r(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:p(()=>[...e[11]||(e[11]=[r("geekpi",-1)])]),_:1}),e[16]||(e[16]=r(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...e[12]||(e[12]=[r("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=r("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[r("LCTT",-1)])]),_:1}),e[20]||(e[20]=r(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[r("Linux 中國",-1)])]),_:1}),e[21]||(e[21]=r(" 榮譽推出",-1))])])}const T=a(s,[["render",u]]);export{C as __pageData,T as default};
